globalThis.MediaInfoProjectMedia = {"tutorial":{"title":"Erklär’s besser","tag":"Eine Anleitung, die wirklich hilft","duration":239.58333333333334,"revision":"30f51d952864","narration":{"id":"de-DE-SeraphinaMultilingualNeural","provider":"Microsoft online speech","gender":"female","language":"de-DE","synthetic":true,"rate":"-5%"},"chapters":[{"title":"Ein Problem. Ein klarer Weg.","kind":"cards","seconds":31.833333333333332,"caption":"Eine gute Anleitung zeigt Ziel, Handlung und sichtbares Ergebnis. Beschränken Sie sich auf eine Funktion.","cards":[["Ziel","Einen Bildausschnitt in die eigene Anleitung einfügen."],["Handlung","Das passende Werkzeug öffnen und den Ausschnitt wählen."],["Ergebnis","Das Bild ist eingefügt und die wichtige Stelle lesbar."]],"why":"Die Person weiss vor dem Start, was sie am Schluss können wird.","start":0.0,"image":"tutorial-01.svg","narration":["Kennen Sie das? Eine Anleitung sieht ordentlich aus, und trotzdem weiss man nicht, wo man klicken soll. Ihr Projekt löst genau dieses Problem.","Die drei Felder zeigen den roten Faden: eine kleine Aufgabe, eine verständliche Handlung und ein Ergebnis, das man erkennen kann.","Wählen Sie deshalb eine einzige Funktion. Eine kurze Anleitung, die wirklich hilft, ist mehr wert als zehn nur angedeutete Tipps."]},{"title":"Beispiel 1 · Der Screenshot","kind":"browser","seconds":35.416666666666664,"caption":"Vergrössern Sie die wichtige Stelle. Nummer, klare Anweisung und Bild gehören zusammen. Der dargestellte Bildschirm ist ein Beispielaufbau.","cards":[["1 · Ansicht vorbereiten","Nur das benötigte Fenster zeigen."],["2 · Ausschnitt wählen","Die wichtige Schaltfläche vollständig erfassen."],["3 · Bild erklären","«Wählen Sie Speichern. Danach liegt die Datei im Projektordner.»"]],"why":"Ein enger Bildausschnitt macht die Entscheidung sichtbar.","start":31.833333333333332,"image":"tutorial-02.svg","narration":["Schauen Sie links: Die Schaltfläche ist vorhanden, geht aber zwischen den vielen anderen Elementen unter. Wer die Oberfläche nicht kennt, muss raten.","Rechts fällt die Entscheidung leichter. Der Ausschnitt zeigt genug Zusammenhang, und die wichtige Stelle ist deutlich grösser. Genau diese Verbindung von Bild und Handlung hilft beim Nachmachen.","Prüfen Sie Ihren eigenen Screenshot: Findet eine andere Person die gemeinte Stelle, ohne dass Sie mit dem Finger darauf zeigen?"]},{"title":"Beispiel 2 · Eine Datei wiederfinden","kind":"path","seconds":32.75,"caption":"Ein konkreter Speicherweg und ein geprüfter Dateiname verhindern Sucherei. Testen Sie den Weg nach dem Schliessen der Datei.","cards":[["Ordner","OneDrive / Informatik / Projekte / Tutorial"],["Name","Tutorial-Screenshot-Vorname.pdf"],["Probe","Datei schliessen → Ordner öffnen → richtige Datei öffnen"]],"why":"Der Test beweist, dass der Ablauf bis zum Ergebnis funktioniert.","start":67.25,"image":"tutorial-03.svg","narration":["Beim Speichern endet die Anleitung oft einen Schritt zu früh. Ein erfolgreicher Klick sagt noch nicht, ob die Datei später wiedergefunden wird.","Der konkrete Ordner und der erkennbare Dateiname geben Ihrer Testperson zwei Anhaltspunkte. Passen Sie beides an Ihren eigenen Speicherort an.","Entscheidend ist der letzte Test: Datei schliessen und von diesem Ordner aus erneut öffnen. Erst jetzt ist der ganze Weg geprüft."]},{"title":"Beispiel 3 · Ein nützlicher Link","kind":"compare","seconds":29.166666666666668,"caption":"Ein Link braucht einen verständlichen Namen und ein geprüftes Ziel. Beim Test soll die andere Person ohne zusätzliche Erklärung weiterkommen.","cards":[["Unklar","«Hier klicken»\nWohin führt das?"],["Hilfreich","«Meine Informatik-Aufträge»\nLink geöffnet, Ziel kontrolliert."],["Ohne-Hilfe-Test","Die Person findet den richtigen Auftrag selbst."]],"why":"Gute Bezeichnungen ersetzen zusätzliche Erklärungen.","start":100.0,"image":"tutorial-04.svg","narration":["Auch ein Link kann eine unnötige Frage auslösen. Bei der linken Beschriftung ist unklar, was nach dem Klick wartet.","Die rechte Variante benennt das Ziel. So kann die Person schon vor dem Öffnen entscheiden, ob dieser Link weiterhilft.","Testen Sie den Link mit dem vorgesehenen Konto. Ein guter Name hilft wenig, wenn das Ziel falsch ist oder der Zugriff fehlt."]},{"title":"So planen Sie ein 75-Sekunden-Video","kind":"timeline","seconds":38.25,"caption":"Planen Sie zuerst den Ablauf: 10 Sekunden Ziel, 50 Sekunden sichtbare Arbeit und 15 Sekunden Ergebnis. Nehmen Sie vorab eine kurze Probe auf.","cards":[["0–10 s · Ziel","Was kann ich danach?"],["10–60 s · Ablauf","Kleine Schritte, gut lesbar, kurze Pausen."],["60–75 s · Kontrolle","Das Ergebnis zeigen und den Erfolg prüfen."]],"why":"Ein Zeitplan lässt Raum für die wichtige Schlusskontrolle.","start":129.16666666666666,"image":"tutorial-05.svg","narration":["Wenn Sie selbst ein Video erstellen, hilft diese Zeitaufteilung. Gemeint ist hier Ihr eigenes Lernprodukt. Zu Beginn reicht ein kurzer Blick auf das Ziel.","Der grösste Teil gehört der sichtbaren Arbeit. Bewegen Sie den Mauszeiger bewusst und lassen Sie nach einem wichtigen Klick kurz Zeit zum Hinschauen.","Reservieren Sie den Schluss für die Kontrolle. Das Beispiel plant fünfundsiebzig Sekunden; Ihr Auftrag erlaubt sechzig bis neunzig. Machen Sie zuerst eine kurze Probeaufnahme."]},{"title":"Vom Zögern zur Verbesserung","kind":"compare","seconds":34.583333333333336,"caption":"Beobachten Sie beim Test. Wenn jemand zögert, ergänzen Sie genau die fehlende Information und testen Sie erneut.","cards":[["Beobachtung","Die Testperson weiss nicht, welches Symbol gemeint ist."],["Verbesserung","Bild enger zuschneiden. Symbol markieren. Namen ergänzen."],["Erneuter Test","Die Person findet das Symbol ohne Hinweis."]],"why":"Eine konkrete Verbesserung zeigt, was Sie gelernt haben.","start":167.41666666666666,"image":"tutorial-06.svg","narration":["Beim Test möchten Sie wahrscheinlich sofort helfen. Warten Sie einen Moment: Das Zögern zeigt Ihnen gerade, welche Information in Ihrer Anleitung fehlt.","Hier ist das Symbol nicht eindeutig. Ein genauerer Ausschnitt und sein Name lösen dieses konkrete Problem. Mehr Text allein würde nicht unbedingt helfen.","Lassen Sie dieselbe Stelle nochmals ausprobieren. Gelingt sie nun ohne Hinweis, können Sie die Verbesserung auch begründen."]},{"title":"Jetzt Ihre eigene Fassung","kind":"cards","seconds":37.583333333333336,"caption":"Wählen Sie eine Vorlage in der Werkbank. Schreiben Sie Ihr Ziel. Planen Sie mindestens fünf sinnvolle Schritte. Verwenden Sie eigene Bilder oder Ihre eigene Aufnahme.","cards":[["01 · Vorlage","Screenshot, Datei wiederfinden oder eigene Idee."],["02 · Material","Mindestens fünf eigene Bilder oder ein 60–90-Sekunden-Video."],["03 · Test","Ohne Hilfe ausprobieren lassen und gezielt verbessern."]],"why":"Beginnen Sie mit einem kleinen Problem, das Ihre Klasse kennt.","start":202.0,"image":"tutorial-07.svg","narration":["Jetzt haben Sie genug Ideen für einen eigenen Start. Wählen Sie in der Werkbank eine Vorlage oder formulieren Sie Ihr eigenes kleines Problem.","Für die Bildanleitung planen Sie mindestens fünf sinnvolle Schritte mit eigenen Bildern. Beim Video zeigen Sie den Ablauf selbst. Die Beispiele hier dienen Ihnen als Orientierung.","Ihr erster Handgriff: Schreiben Sie einen Satz dazu, was eine andere Person am Schluss selbstständig können soll. Danach planen Sie im Cockpit Ihre nächste Arbeitsetappe."]}]},"cockpit":{"title":"Mein digitales Cockpit","tag":"Weniger suchen. Klarer beginnen.","duration":244.5,"revision":"30f51d952864","narration":{"id":"de-DE-SeraphinaMultilingualNeural","provider":"Microsoft online speech","gender":"female","language":"de-DE","synthetic":true,"rate":"-5%"},"chapters":[{"title":"Vier Bereiche. Ein schneller Einstieg.","kind":"board","seconds":34.583333333333336,"caption":"Ein Cockpit beantwortet vier Fragen: Was tue ich zuerst? Was steht an? Wo arbeite ich? Was will ich erreichen?","cards":[["Aufgaben","Zuerst: Scan prüfen und als PDF speichern."],["Termine","Abgabe und Vorbereitung unterscheiden."],["Links","Direkt zu Aufträgen und Arbeitsdateien."],["Ziel","Ein erreichbares Ergebnis für diese Woche."]],"why":"Alle Bereiche helfen bei einer konkreten Entscheidung.","start":0.0,"image":"cockpit-01.svg","narration":["Die Lektion beginnt. Wissen Sie sofort, womit Sie weiterarbeiten? Ihr persönliches Cockpit soll Ihnen genau diese Entscheidung erleichtern.","Die Termine zeigen, was näher rückt. Sie ersetzen aber noch keine konkrete Aufgabe: Vor einem Abgabetermin braucht es Zeit zum Prüfen.","Passende Links verkürzen den Weg zur Arbeit.","Und ein erreichbares Ziel gibt der Woche eine Richtung. Jeder Bereich hat damit eine eigene Aufgabe."]},{"title":"Beispiel 1 · Schule im Griff","kind":"board","seconds":38.083333333333336,"caption":"Dieses Schulbeispiel enthält drei Aufgaben, zwei erfundene Termine, drei Linknamen und ein Ziel. Übernehmen Sie echte Termine nur aus Ihrer Quelle.","cards":[["Meine Aufgaben","ZUERST · Scan öffnen und prüfen\nTutorial-Bilder ergänzen\nQuellenlinks kontrollieren"],["Termine · Übung","Dienstag, 10:00 · Zwischentest\nFreitag, 12:00 · Ergebnis zeigen"],["Meine Links","Informatik-Aufträge\nMein Projektordner\nMein OneNote-Notizbuch"],["Mein Ziel","Bis Freitag: Tutorial so verbessern, dass der Ablauf ohne Hilfe gelingt."]],"why":"Ein Verb und ein sichtbares Ergebnis machen Aufgaben ausführbar.","start":34.583333333333336,"image":"cockpit-02.svg","narration":["Im Schulbeispiel fällt ein Eintrag zuerst auf. Das ist Absicht: Drei gleich wichtige Aufgaben würden die Entscheidung wieder an Sie zurückgeben.","Der Zwischentest liegt vor der Abgabe. So bleibt noch Zeit, etwas zu verbessern. Die dargestellten Termine sind erfunden; verwenden Sie später Ihre tatsächlichen Angaben.","Benennen Sie Links nach dem Arbeitsziel.","Das Wochenziel beschreibt ein überprüfbares Ergebnis. Daran erkennen Sie, ob Ihre Arbeit geholfen hat."]},{"title":"Beispiel 2 · Schnupperlehre","kind":"board","seconds":34.416666666666664,"caption":"Die gleiche Struktur hilft bei einer anderen Situation. Dieses Beispiel ist erfunden und enthält keine fremden Kontaktdaten.","cards":[["Vorbereiten","3 Fragen zum Beruf notieren\nAnreise prüfen\nBenötigte Unterlagen ordnen"],["Termine · Übung","Montag · Vorbereitung prüfen\nMittwoch · Schnuppertag"],["Schnellzugriffe","Meine Fragen\nMeine Packliste\nÖffentlicher Fahrplan"],["Nächstes Ziel","Am Vortag liegen Fragen und benötigte Unterlagen bereit."]],"why":"Sie passen die Inhalte an Ihren Alltag an, die Orientierung bleibt.","start":72.66666666666667,"image":"cockpit-03.svg","narration":["Die gleiche Ordnung funktioniert auch vor einer Schnupperlehre. Hier werden aus dem grossen Vorhaben kleine Vorbereitungen, die Sie einzeln erledigen können.","Besonders hilfreich ist die Kontrolle am Vortag. Eine fehlende Unterlage lässt sich dann meist noch beschaffen.","Die Schnellzugriffe führen direkt zu dem, was Sie brauchen.","Übernehmen Sie also die Struktur, aber füllen Sie sie mit Ihrem Alltag. Auch diese Angaben sind nur ein Übungsbeispiel."]},{"title":"Beispiel 3 · Meine Lernwoche","kind":"board","seconds":33.833333333333336,"caption":"Ein Wochenplan wird nützlich, wenn grosse Vorhaben in kleine nächste Handlungen zerlegt sind. Die Termine hier sind Übungsangaben.","cards":[["Diese Woche","5 Begriffe mit Beispielen notieren\nPDF auf 3 Angaben prüfen\nEine offene Frage klären"],["Termine · Übung","Dienstag · Selbsttest\nDonnerstag · Fragen besprechen"],["Direkt öffnen","Lernnotizen\nÜbungsdossier\nAufgabenübersicht"],["Mein Ziel","Die fünf Begriffe am Donnerstag ohne Nachschlagen erklären."]],"why":"Das Ziel lässt sich prüfen; der erste Schritt ist klein genug.","start":107.08333333333333,"image":"cockpit-04.svg","narration":["Bei einer Lernwoche ist die Gefahr gross, einfach nur Lernen einzutragen. Hier sehen Sie stattdessen kleine Tätigkeiten, mit denen man wirklich anfangen kann.","Ein Selbsttest vor dem nächsten Unterricht macht offene Fragen sichtbar.","Die verlinkten Notizen halten das Material griffbereit.","Das Ziel geht einen Schritt weiter als Lesen: Die Begriffe sollen ohne Nachschlagen erklärt werden. So prüfen Sie Ihr Verständnis statt nur Ihre Arbeitszeit."]},{"title":"Von «lernen» zu einem Auftrag","kind":"compare","seconds":31.166666666666668,"caption":"Zu grosse oder vage Einträge blockieren den Start. Formulieren Sie eine sichtbare Handlung und nennen Sie bei Bedarf den ersten kleinen Schritt.","cards":[["Zu vage","«Informatik machen»\nWo soll ich anfangen?"],["Ausführbar","«Drei PDF-Seiten auf Lesbarkeit prüfen»"],["Erster Schritt","PDF am Notebook öffnen und auf Seite 1 zoomen."]],"why":"Eine klare Aufgabe senkt die Hürde, tatsächlich anzufangen.","start":140.91666666666666,"image":"cockpit-05.svg","narration":["Vergleichen Sie diese Einträge. Der linke klingt nach Arbeit, lässt aber offen, wo sie beginnt und wann sie fertig ist.","Die mittlere Fassung nennt eine Handlung und einen begrenzten Umfang. Das ist besonders nützlich, wenn nur noch wenige Minuten bleiben.","Rechts steht bereits der erste Handgriff. Pausieren Sie kurz und formulieren Sie einen eigenen unklaren Eintrag genauso konkret um."]},{"title":"Der 10-Sekunden-Test","kind":"cards","seconds":33.833333333333336,"caption":"Schliessen und öffnen Sie die OneNote-Seite. Finden Sie Aufgabe, Termin und Link jeweils in etwa zehn Sekunden. Das ist ein Testziel, keine Geschwindigkeitsnote.","cards":[["Nächste Aufgabe?","Das Wort ZUERST fällt direkt auf."],["Nächster Termin?","Datum und Anlass stehen zusammen."],["Benötigte Datei?","Der benannte Link führt zum richtigen Ort."]],"why":"Die langsamste Stelle zeigt Ihnen, was Sie verbessern sollten.","start":172.08333333333334,"image":"cockpit-06.svg","narration":["Ob das Cockpit gut gestaltet ist, zeigt sich beim Wiederöffnen. Finden Sie die nächste Aufgabe, ohne die ganze Seite lesen zu müssen?","Suchen Sie danach den nächsten Termin. Rund zehn Sekunden je Frage sind eine Orientierung, keine Geschwindigkeitsnote.","Öffnen Sie schliesslich den benötigten Link. Wo Sie suchen oder nachdenken mussten, vereinfachen Sie die Seite. Zusätzliche Dekoration ist dafür oft gar nicht nötig."]},{"title":"Jetzt Ihr persönliches Cockpit","kind":"path","seconds":38.583333333333336,"caption":"Wählen Sie eine Vorlage, füllen Sie die vier Bereiche und kopieren Sie den Entwurf nach OneNote. Dort setzen und testen Sie Links und echte Aufgaben-Kästchen.","cards":[["Werkbank","Inhalt entwerfen und verständlich benennen."],["OneNote","In den persönlichen Bereich übertragen und nutzbar machen."],["Alltag","Am Anfang ansehen, am Schluss aktualisieren."]],"why":"Ein Cockpit wird durch regelmässige Nutzung wertvoll.","start":205.91666666666666,"image":"cockpit-07.svg","narration":["In der Werkbank entwerfen Sie zunächst den Inhalt. Wählen Sie eine passende Vorlage und ersetzen Sie die Beispiele durch Ihre eigenen Angaben.","Anschliessend übertragen Sie den Entwurf nach OneNote. Dort setzen Sie echte Aufgabenmarkierungen und Links und prüfen, ob sie funktionieren.","Ihr persönliches OneNote-Cockpit ist das Produkt dieses Projekts. Das Cockpit auf der Projektwebsite hilft Ihnen zusätzlich, die verfügbare Lektionszeit zu planen. Nutzen Sie beide bewusst für ihren jeweiligen Zweck."]}]},"dokumente":{"title":"Alles in einer PDF","tag":"Ein Dossier, das man wirklich benutzen kann","duration":247.75,"revision":"30f51d952864","narration":{"id":"de-DE-SeraphinaMultilingualNeural","provider":"Microsoft online speech","gender":"female","language":"de-DE","synthetic":true,"rate":"-5%"},"chapters":[{"title":"Drei Seiten. Eine brauchbare Datei.","kind":"pages","seconds":31.916666666666668,"caption":"Ein gutes Dossier verbindet drei zusammengehörige Seiten: sinnvoll geordnet, vollständig und gut lesbar in einer einzigen PDF.","cards":[["1 · Überblick","Worum geht es?"],["2 · Details","Was muss ich wissen?"],["3 · Checkliste","Was tue ich als Nächstes?"]],"why":"Denken Sie an die Person, die mit dem Dossier arbeiten wird.","start":0.0,"image":"dokumente-01.svg","narration":["Stellen Sie sich vor, Sie erhalten diese Datei kurz vor einem Anlass. Was müssten Sie als Erstes wissen? Mit dieser Frage beginnt ein gutes Dossier.","Drei Seiten einfach zusammenzufügen reicht noch nicht. Die Informationen sollen in einer Reihenfolge stehen, die der nutzenden Person weiterhilft.","Die letzte Seite kann dann die nächste Handlung erleichtern. Ihre PDF wird so zu einem brauchbaren Begleiter."]},{"title":"Beispiel 1 · Open-Air Nord","kind":"pages","seconds":37.166666666666664,"caption":"Das bereitgestellte Übungsmaterial wird B, C, A geordnet: erst Tagesinfo, dann Anreise, zuletzt Packliste. Alle Angaben sind erfunden.","cards":[["1 · Tagesinfo · B","Beginn: 14:00\nWas erwartet mich?"],["2 · Anreise · C","Geplante Ankunft: 13:22\nWie komme ich hin?"],["3 · Packliste · A","Regenjacke einpacken\nWas nehme ich mit?"]],"why":"Die Reihenfolge folgt den Fragen der nutzenden Person.","start":31.916666666666668,"image":"dokumente-02.svg","narration":["Beim erfundenen Open-Air beginnt die Datei mit der Tagesinfo. Erst wenn Sie den Anlass kennen, ergeben die weiteren Angaben einen Zusammenhang.","Danach folgt die Anreise. Die geplante Ankunft um dreizehn Uhr zweiundzwanzig lässt sich nun mit dem Beginn um vierzehn Uhr vergleichen.","Die Packliste schliesst mit einer Handlung ab. Deshalb wird das bereitgestellte Material hier in der Reihenfolge B, C, A verwendet. Die Buchstaben bestimmen also nicht automatisch die richtige Ordnung."]},{"title":"Beispiel 2 · Lernunterlagen","kind":"pages","seconds":31.666666666666668,"caption":"Drei eigene Lernblätter können vom Überblick über ein durchgerechnetes Beispiel zur eigenen Übung führen. Die Reihenfolge folgt dem Lernweg.","cards":[["1 · Überblick","Begriffe und Regeln"],["2 · Beispiel","Ein vollständig erklärter Ablauf"],["3 · Übung","Eine Aufgabe zum selbstständigen Ausprobieren"]],"why":"Zusammengehörige Blätter bilden einen nachvollziehbaren Weg.","start":69.08333333333333,"image":"dokumente-03.svg","narration":["Bei Lernunterlagen funktioniert ein ähnlicher Gedanke: Zuerst hilft ein Überblick, das Thema einzuordnen.","Das anschliessende Beispiel macht sichtbar, wie die Idee angewendet wird. Es sollte deshalb zum gleichen Thema gehören und gut lesbar sein.","Eine passende Übung lässt Sie das Verständnis prüfen. Fragen Sie bei jeder Seite: Was kann die Person damit tun, was vorher noch nicht möglich war?"]},{"title":"Beispiel 3 · Ein Vereinsanlass","kind":"pages","seconds":35.75,"caption":"Ein weiterer erfundener Aufbau: Programm, öffentlicher Lageplan und Materialliste. Verwenden Sie keine privaten Kontaktdaten.","cards":[["1 · Programm","Wann beginnt welcher Teil?"],["2 · Lageplan","Wo ist der Treffpunkt?"],["3 · Materialliste","Was muss ich mitbringen?"]],"why":"Wählen Sie nur drei Seiten, die dieselbe Situation unterstützen.","start":100.75,"image":"dokumente-04.svg","narration":["Auch ein Vereinsdossier kann so aufgebaut sein. Das Programm erklärt zunächst, was geplant ist. Es geht hier um ein erfundenes Beispiel.","Die Ortsangaben helfen anschliessend, tatsächlich dort anzukommen. Eine abgeschnittene Adresse wäre deshalb mehr als ein Schönheitsfehler.","Die Materialliste unterstützt die Vorbereitung. Die drei Beispiele zeigen Ihnen verschiedene Themen, aber dieselbe wichtige Frage: Passt die Ordnung zum späteren Gebrauch?"]},{"title":"Lesbarkeit vor Schönheit","kind":"compare","seconds":35.25,"caption":"Dunkle Ränder, Schatten oder abgeschnittene Zeilen erschweren die Nutzung. Prüfen Sie jede Seite vergrössert und erfassen Sie schlechte Seiten neu.","cards":[["Problem","Rechter Rand fehlt.\nDie Uhrzeit ist abgeschnitten."],["Korrektur","Seite flach legen.\nGleichmässiges Licht.\nAlle Ränder im Bild."],["Kontrolle","Kleinste wichtige Angabe vergrössert lesen."]],"why":"Eine neue Aufnahme ist oft schneller als langes Reparieren.","start":136.5,"image":"dokumente-05.svg","narration":["Hier sieht man einen typischen Fehler: Wenn beim Aufnehmen ein Rand fehlt, kann auch eine wichtige Angabe verschwinden. Das lässt sich durch Zusammenfügen nicht reparieren.","Legen Sie das Blatt flach hin und sorgen Sie für gleichmässiges Licht. Kontrollieren Sie alle Ränder, bevor Sie weitergehen.","Zoomen Sie danach auf eine kleine Angabe. Ist sie unleserlich, nehmen Sie die Seite nochmals auf. Dieser kurze Check spart Ihnen eine spätere Reparaturrunde."]},{"title":"Der Härtetest am Notebook","kind":"cards","seconds":37.916666666666664,"caption":"Öffnen Sie die exportierte PDF ausserhalb des Erstellungsprogramms. Prüfen Sie Seitenzahl und Ordnung, finden Sie drei Angaben und notieren Sie die Dateigrösse.","cards":[["Struktur","Genau 3 Seiten, aufrecht und in der geplanten Reihenfolge."],["Inhalt","Beginn, Ankunft und Regenausrüstung finden."],["Datei","Sinnvoll benannt, richtiger Ordner, erneut geöffnet."]],"why":"Erst der Test an der fertigen Datei zeigt, ob der Export gelungen ist.","start":171.75,"image":"dokumente-06.svg","narration":["Prüfen Sie jetzt die exportierte Datei selbst. Eine gute Vorschau im Scanprogramm beweist noch nicht, dass die fertige PDF vollständig ist.","Suchen Sie drei konkrete Informationen. Im Open-Air-Beispiel sind das Beginn, Ankunft und Regenjacke. So testen Sie gleichzeitig Inhalt und Nutzbarkeit.","Kontrollieren Sie auch den Dateinamen und notieren Sie die Dateigrösse. Grösser ist nicht automatisch besser; entscheidend sind vollständige Seiten und lesbare Angaben."]},{"title":"Jetzt Ihr eigenes Dossier","kind":"path","seconds":38.083333333333336,"caption":"Wählen Sie Scanweg mit Papier oder Bildweg mit den drei Übungsbildern. Planen Sie die Reihenfolge in der Werkbank und erstellen Sie dann Ihre echte PDF.","cards":[["Planen","Material wählen, Reihenfolge begründen."],["Erstellen","3 Seiten in einer gemeinsamen PDF speichern."],["Nachweisen","Fundstellen, Dateiname und Dateigrösse im Check notieren."]],"why":"Der Dossier-Plan begleitet Ihre PDF; er ersetzt sie nicht.","start":209.66666666666666,"image":"dokumente-07.svg","narration":["Wählen Sie nun Ihren Arbeitsweg: mit Papier scannen oder mit den bereitgestellten Bildern arbeiten. Begründen Sie zuerst Ihre Seitenreihenfolge.","Erstellen Sie danach eine gemeinsame PDF mit drei Seiten. Der ausgefüllte Plan in der Werkbank begleitet diese Arbeit; die PDF müssen Sie zusätzlich erzeugen.","Zum Schluss öffnen Sie die Datei vom tatsächlichen Speicherort. Halten Sie Ihr Prüfergebnis fest. Für den nächsten Start gehört dieser Speicherort auch in Ihren Lektionsabschluss."]}]},"faktencheck":{"title":"Echt oder Fake?","tag":"Ein Urteil, dessen Weg man nachvollziehen kann","duration":248.25,"revision":"30f51d952864","narration":{"id":"de-DE-SeraphinaMultilingualNeural","provider":"Microsoft online speech","gender":"female","language":"de-DE","synthetic":true,"rate":"-5%"},"chapters":[{"title":"Behauptung → Belege → Urteil","kind":"cards","seconds":31.583333333333332,"caption":"Beginnen Sie mit einem überprüfbaren Satz. Lesen Sie zwei brauchbare Quellen verschiedener Organisationen. Das Urteil darf nur so weit gehen wie die Belege.","cards":[["Behauptung","Was genau soll wahr sein?"],["Belege","Was steht tatsächlich in Quelle 1 und Quelle 2?"],["Urteil","Was folgt daraus – mit welcher Einschränkung?"]],"why":"Zwei verlinkte Suchtreffer sind noch keine nachvollziehbare Prüfung.","start":0.0,"image":"faktencheck-01.svg","narration":["Eine Behauptung klingt überzeugend. Aber welche Frage müssten Sie beantworten, um sie wirklich zu prüfen? Beginnen Sie mit einem genauen Satz.","Zwei Suchtreffer allein genügen nicht. Entscheidend ist, ob die Quellen genau zu dieser Aussage etwas belegen. Lesen Sie dafür die passenden Stellen selbst.","Erst danach folgt Ihr Urteil. Es darf auch offenbleiben, wenn die Belege noch nicht reichen."]},{"title":"Beispiel 1 · «Inkognito = unsichtbar»","kind":"evidence","seconds":37.416666666666664,"caption":"Google und Mozilla erklären: Privates Surfen beschränkt lokale Spuren, macht aber nicht anonym. Die genaue Funktionsweise hängt vom Browser ab. Die Quellen sind unter dem Video verlinkt.","cards":[["Google · Chrome-Hilfe","Websites und Netzwerkbetreiber können Aktivitäten möglicherweise beobachten."],["Mozilla · Firefox-Hilfe","Privater Modus macht im Internet nicht anonym."],["Begründetes Urteil","Die pauschale Behauptung ist falsch: weniger lokale Spuren bedeutet nicht unsichtbar."]],"why":"Die Begründung nennt beide Belege und unterscheidet lokal von online.","start":31.583333333333332,"image":"faktencheck-02.svg","narration":["Die Aussage über den Inkognitomodus vermischt zwei Dinge: Spuren auf dem eigenen Gerät und Sichtbarkeit im Internet. Genau diese Unterscheidung ist entscheidend.","Die Hilfeseiten von Google und Mozilla erläutern unterschiedliche Browser. Beide widersprechen aber der Vorstellung, privates Surfen mache Sie im Internet anonym.","Das Urteil rechts ist deshalb begründet. Verknüpfen Sie Ihre Schlussfolgerung ausdrücklich mit den gelesenen Belegen, statt nur ein rotes Falsch darüberzusetzen."]},{"title":"Beispiel 2 · Was bleibt gespeichert?","kind":"compare","seconds":36.5,"caption":"Die Aussage «Im privaten Modus wird alles gelöscht» ist zu pauschal. Laut Google und Mozilla bleiben heruntergeladene Dateien erhalten. Prüfen Sie die beschriebenen Browser getrennt.","cards":[["Behauptung","«Nach dem Schliessen ist alles weg.»"],["Passender Beleg","Heruntergeladene Dateien bleiben auf dem Gerät."],["Genauer formuliert","Lokale Surfspuren werden eingeschränkt; Downloads verschwinden dadurch nicht."]],"why":"Wörter wie «alles» und «niemand» verlangen besonders genaue Belege.","start":69.0,"image":"faktencheck-03.svg","narration":["Achten Sie bei der nächsten Behauptung auf das Wort alles. Solche absoluten Wörter verlangen besonders genaue Belege.","Die heruntergeladene Datei ist hier das entscheidende Gegenbeispiel. Laut den genannten Hilfeseiten bleibt sie auch nach dem Schliessen der privaten Sitzung auf dem Gerät.","Damit lässt sich die pauschale Aussage widerlegen. Daraus folgt jedoch nicht, dass alle Browser jede Art von Daten genau gleich behandeln. Bleiben Sie bei dem, was Ihre Quellen tatsächlich erklären."]},{"title":"Beispiel 3 · Ein Bild ohne Kontext","kind":"evidence","seconds":36.833333333333336,"caption":"Erfundener Übungsfall: Ein Post behauptet, ein Bild sei von heute. Ein Vereinsarchiv zeigt dasselbe Motiv mit älterem Datum. Ohne geklärten Ursprung bleibt der aktuelle Zeitpunkt unbewiesen.","cards":[["Post · Übungsfall","«Dieses Foto zeigt den heutigen Anlass.»"],["Archiv · Übungsfall","Dasselbe Motiv erscheint mit einem älteren Datum."],["Vorsichtiges Urteil","«Von heute» ist nicht ausreichend belegt. Den Ursprung des Fotos weiter prüfen."]],"why":"Ein offenes Urteil ist besser als eine Sicherheit, die Ihre Belege nicht tragen.","start":105.5,"image":"faktencheck-04.svg","narration":["Dieser Bildfall ist erfunden. Ein Post behauptet, ein Foto stamme von heute. Wie würden Sie das überprüfen?","Ein älterer Archiveintrag mit demselben Motiv ist ein Grund, genauer hinzusehen. Er beweist allein noch nicht, dass es exakt dieselbe Aufnahme ist.","Deshalb bleibt das aktuelle Datum zunächst unbewiesen. Ein vorsichtiges Urteil ist hier eine Stärke. Ein konkreter nächster Prüfschritt wäre, den Ursprung der Aufnahme zu klären."]},{"title":"Eine Quelle so festhalten, dass sie prüfbar ist","kind":"cards","seconds":34.166666666666664,"caption":"Notieren Sie Organisation, Seitentitel, vollständigen Link, Abschnitt und Abrufdatum. Schreiben Sie den Beleg in eigenen Worten und nennen Sie seine Grenze.","cards":[["Fundort","Google Chrome-Hilfe · Inkognitomodus\nAbschnitt: Was auf dem Gerät gespeichert wird"],["Beleg","Downloads bleiben nach Ende der Sitzung erhalten."],["Grenze","Diese Quelle erklärt Chrome. Nicht ungeprüft auf alle Programme übertragen."]],"why":"Eine andere Person kann Ihren Beleg gezielt wiederfinden.","start":142.33333333333334,"image":"faktencheck-05.svg","narration":["Eine andere Person soll Ihren Gedankengang nachprüfen können. Ein Link auf eine lange Hilfeseite reicht dafür oft nicht. Notieren Sie auch den passenden Abschnitt und das Abrufdatum.","Fassen Sie anschliessend den entscheidenden Beleg in eigenen Worten zusammen. Daran merken Sie auch, ob Sie ihn verstanden haben.","Die Grenze daneben verhindert eine zu grosse Schlussfolgerung. Eine Erklärung zu Chrome gilt nicht automatisch für jedes andere Programm."]},{"title":"Klar gestalten, ehrlich urteilen","kind":"board","seconds":35.5,"caption":"Eine gute Faktencheck-Karte trennt Behauptung, Belege, Urteil und Quellen. Die Quellenlinks und die Einschränkung bleiben auch in einer kurzen Fassung sichtbar.","cards":[["Behauptung","Ein genauer Satz."],["Belege","Quelle 1 und Quelle 2 gegenüberstellen."],["Urteil","Stimmt / teilweise / falsch / offen – begründet."],["Quellen","Beide Links, Fundstellen und Abrufdaten."]],"why":"Die Gestaltung macht Ihren Gedankengang überprüfbar.","start":176.5,"image":"faktencheck-06.svg","narration":["Ihre Faktencheck-Karte soll den Prüfweg sichtbar machen. Die Behauptung steht deshalb getrennt von Ihrer eigenen Bewertung.","Stellen Sie die zwei Belege so gegenüber, dass Gemeinsamkeiten oder Unterschiede auffallen.","Formulieren Sie dann das Urteil samt wichtiger Einschränkung. Auch teilweise richtig oder offen können passende Ergebnisse sein.","Die Quellen bleiben auffindbar. Kürzen Sie die Gestaltung nicht gerade an der Stelle, an der die Überprüfbarkeit beginnt."]},{"title":"Jetzt Ihre eigene Prüfung","kind":"path","seconds":36.25,"caption":"Wählen Sie eine Vorlage. Lesen Sie die Quellen selbst, auch wenn Sie das Beispielvideo kennen. Verknüpfen Sie Ihr Urteil mit den tatsächlich gelesenen Belegen.","cards":[["Eingrenzen","Eine Aussage und eine genaue Prüffrage."],["Lesen","Zwei Organisationen, passende Fundstellen."],["Begründen","Eigenes Urteil mit einer ehrlichen Einschränkung."]],"why":"Das Beispiel zeigt die Methode. Ihre Arbeit zeigt Ihre eigene Prüfung.","start":212.0,"image":"faktencheck-07.svg","narration":["Wählen Sie jetzt eine Vorlage und grenzen Sie Ihre eigene Prüffrage ein. Je genauer sie ist, desto leichter erkennen Sie passende Belege.","Lesen Sie die verlinkten Originalquellen selbst, auch wenn Sie das Beispiel gerade gesehen haben. Zwei Organisationen bieten unterschiedliche Bezugspunkte; entscheidend bleibt der Inhalt.","Schreiben Sie zum Schluss, was Sie belegen können und was noch offen ist. Ihr erster Schritt heute ist eine klare Prüffrage, nicht schon das fertige Urteil."]}]},"lifehacks":{"title":"Fünf Tricks, die bleiben","tag":"Kleine Handgriffe. Sichtbar getestet.","duration":289.9166666666667,"revision":"30f51d952864","narration":{"id":"de-DE-SeraphinaMultilingualNeural","provider":"Microsoft online speech","gender":"female","language":"de-DE","synthetic":true,"rate":"-5%"},"chapters":[{"title":"Ein Tipp braucht einen Beweis","kind":"cards","seconds":32.0,"caption":"Eine gute Tippkarte verbindet Nutzen, zwei bis drei Schritte, eigenen Test und eine Grenze. Ein hübsches Symbol allein zeigt noch keinen Test.","cards":[["Hilft, wenn …","Ich eine bestimmte Information suche."],["So geht es","Programm nennen, Handlung kurz erklären."],["Mein Test","Sichtbares Ergebnis zeigen und eine Grenze nennen."]],"why":"Ihre Sammlung soll anderen beim Ausprobieren helfen.","start":0.0,"image":"lifehacks-01.svg","narration":["Ein guter Digitaltipp löst eine Situation, die Sie wirklich kennen. Beginnen Sie deshalb nicht mit einem Tastenkürzel, sondern mit der Frage: Wann hilft mir das?","Erklären Sie den Handgriff so knapp, dass eine andere Person ihn ausprobieren kann. Nennen Sie auch das verwendete Programm.","Ihr eigener Test macht daraus einen verlässlichen Tipp. Dazu gehört ebenso eine Grenze: Wann funktioniert er nicht wie erwartet?"]},{"title":"Tipp 1 · Auf einer Seite suchen","kind":"browser","seconds":37.833333333333336,"caption":"Beispiel Chrome unter Windows: Strg und F öffnet die Suche auf der aktuellen Seite. Geben Sie einen vorhandenen Begriff ein und prüfen Sie den markierten Treffer.","cards":[["Tasten","Strg + F"],["Eigener Test","Im Übungstext «Abgabe» suchen. Der Treffer wird markiert."],["Grenze","Sucht auf der aktuellen Seite, nicht im ganzen Internet."]],"why":"Zeigen Sie im eigenen Bild den Suchbegriff und einen Treffer.","start":32.0,"image":"lifehacks-02.svg","narration":["Hier wird in Chrome unter Windows auf einer geöffneten Seite gesucht. Mit Steuerung und F erscheint das Suchfeld. Verwenden Sie einen Begriff, der tatsächlich auf der Seite steht.","Die Markierung zeigt den Erfolg Ihres Tests. Für die Tippkarte sind deshalb Suchbegriff und Treffer gemeinsam wichtig.","Diese Suche durchsucht die aktuelle Seite. Wer stattdessen Informationen im ganzen Internet sucht, braucht einen anderen Weg. Genau solche Grenzen machen Ihre Erklärung nützlich."]},{"title":"Tipp 2 · Einen Tab zurückholen","kind":"browser","seconds":37.5,"caption":"Beispiel Chrome unter Windows: Öffnen und schliessen Sie eine harmlose Seite. Mit Strg, Umschalt und T öffnen Sie einen kürzlich geschlossenen Tab wieder.","cards":[["Tasten","Strg + Umschalt + T"],["Eigener Test","Eine Übungsseite schliessen und wieder öffnen."],["Grenze","Privat geschlossene Tabs werden auf diesem Weg nicht wiederhergestellt."]],"why":"Testen Sie an einer Seite ohne ungespeicherte Arbeit.","start":69.83333333333333,"image":"lifehacks-03.svg","narration":["Ein Tab wurde versehentlich geschlossen. Für Ihren Versuch nehmen Sie bewusst eine harmlose Seite ohne ungespeicherte Arbeit.","In Chrome unter Windows können Sie mit Steuerung, Umschalt und T einen kürzlich geschlossenen Tab wieder öffnen. Der zurückgekehrte Tab ist Ihr sichtbarer Beleg.","Das ist keine allgemeine Rettungsfunktion für verlorene Eingaben. Privat geschlossene Tabs werden auf diesem Weg ebenfalls nicht wiederhergestellt. Beschreiben Sie also genau, was Sie getestet haben."]},{"title":"Tipp 3 · Gezielt aufnehmen","kind":"browser","seconds":36.833333333333336,"caption":"Unter Windows öffnet Windows, Umschalt und S die Screenshot-Auswahl. Wählen Sie den wichtigen Bereich. Prüfen Sie das eingefügte Bild auf Lesbarkeit und private Angaben.","cards":[["Tasten","Windows + Umschalt + S"],["Eigener Test","Nur den relevanten Bereich aufnehmen und in die Tippkarte einfügen."],["Grenze","Zu kleine Ausschnitte können wichtige Zusammenhänge abschneiden."]],"why":"Ihr Bild zeigt die Information, die Ihre Erklärung braucht.","start":107.33333333333333,"image":"lifehacks-04.svg","narration":["Für eine Anleitung ist oft nur ein kleiner Teil des Bildschirms wichtig. Die Tastenkombination Windows, Umschalt und S öffnet unter Windows die Auswahl für einen Screenshot.","Der gewählte Ausschnitt soll die entscheidende Stelle zeigen, aber noch verständlich bleiben. Ein enger Ausschnitt ist nur dann besser, wenn der nötige Zusammenhang erhalten bleibt.","Prüfen Sie das eingefügte Bild auf Lesbarkeit und private Angaben. Ein sauberer eigener Screenshot ist zugleich der Nachweis Ihres Versuchs."]},{"title":"Tipp 4 · Eine Aufgabe klar abhaken","kind":"board","seconds":35.916666666666664,"caption":"Erstellen Sie in OneNote eine echte Aufgabenmarkierung. Formulieren Sie ein sichtbares Ergebnis. Haken Sie erst ab, wenn Sie dieses Ergebnis geprüft haben.","cards":[["Aufgabe","PDF öffnen und alle 3 Seiten prüfen."],["Erster Schritt","Datei im Projektordner öffnen."],["Test","Aufgabe ausführen, Ergebnis kontrollieren, Kästchen abhaken."],["Grenze","Ein Kästchen löst keine automatische Erinnerung aus."]],"why":"Die Checkliste verbindet eine Handlung mit einer ehrlichen Kontrolle.","start":144.16666666666666,"image":"lifehacks-05.svg","narration":["Auch eine einfache Checkliste kann ein guter Tipp sein. Entscheidend ist der Inhalt: Die Aufgabe beschreibt hier ein Ergebnis, das Sie wirklich kontrollieren können.","Der kleine erste Schritt erleichtert den Einstieg.","In OneNote setzen Sie eine echte Aufgabenmarkierung. Erst nach der Kontrolle wird sie abgehakt. Ein Häkchen soll etwas bedeuten.","Es erzeugt allerdings nicht automatisch eine Erinnerung. Halten Sie diese Grenze auch in Ihrer Tippkarte fest."]},{"title":"Tipp 5 · PDF vor der Abgabe prüfen","kind":"pages","seconds":35.5,"caption":"Öffnen Sie die exportierte PDF als eigene Datei. Prüfen Sie Seitenzahl, Lesbarkeit und einen wichtigen Inhalt. So entdecken Sie Fehler, die im Arbeitsprogramm nicht auffielen.","cards":[["Anzahl","Sind alle erwarteten Seiten enthalten?"],["Lesbarkeit","Sind kleine Angaben und Ränder lesbar?"],["Inhalt","Finde ich eine vorher festgelegte Information?"]],"why":"Der Test untersucht das tatsächliche Produkt, das Sie abgeben.","start":180.08333333333334,"image":"lifehacks-06.svg","narration":["Dieser Tipp wirkt unspektakulär, verhindert aber unangenehme Überraschungen. Öffnen Sie die exportierte PDF als eigene Datei und zählen Sie die Seiten.","Vergrössern Sie eine kleine Angabe. Prüfen Sie auch, ob am Rand etwas fehlt. Die ursprüngliche Arbeitsdatei kann korrekt aussehen, obwohl beim Export etwas schiefging.","Suchen Sie abschliessend eine wichtige Information. So untersuchen Sie das Produkt, das später tatsächlich jemand erhält."]},{"title":"Von einem Versprechen zu einem Nutzen","kind":"compare","seconds":34.416666666666664,"caption":"Schreiben Sie, was bei Ihrem Test tatsächlich besser ging. Vermeiden Sie erfundene Zeitersparnisse. Prüfen Sie einen Tipp zusätzlich mit einer anderen Person.","cards":[["Zu ungenau","«Dieser Trick spart mega viel Zeit.»"],["Nachvollziehbar","«Ich finde den Abgabetermin direkt über den markierten Treffer.»"],["Test zu zweit","Die Person führt den Tipp nur mit Ihrer Karte aus."]],"why":"Eine konkrete Beobachtung ist überzeugender als ein grosses Versprechen.","start":215.58333333333334,"image":"lifehacks-07.svg","narration":["Vergleichen Sie diese beiden Nutzenversprechen. Das linke klingt begeistert, sagt aber wenig darüber, was der Tipp konkret verbessert.","Rechts steht eine beobachtbare Wirkung. Dafür müssen Sie weder eine Zeitersparnis erfinden noch behaupten, der Trick helfe immer.","Geben Sie eine Karte jemand anderem. Funktioniert der Versuch ohne Ihre mündlichen Ergänzungen? Wenn nicht, haben Sie den besten Hinweis für Ihre nächste Verbesserung."]},{"title":"Jetzt Ihre fünf Tippkarten","kind":"path","seconds":39.916666666666664,"caption":"Wählen Sie fünf unterschiedliche Tricks. Mindestens zwei sollen für Sie noch keine Routine sein. Nutzen Sie eine Vorlage und ergänzen Sie eigene Tests, Bilder und Grenzen.","cards":[["Wählen","Fünf Tricks, die in Ihren Alltag passen."],["Testen","Eigener Versuch, sichtbares Ergebnis, eigene Darstellung."],["Verbessern","Eine Karte ohne Zusatzhilfe testen lassen."]],"why":"Ihr persönlicher Favorit bekommt eine Begründung, keine blosse Krone.","start":250.0,"image":"lifehacks-08.svg","narration":["Wählen Sie nun fünf unterschiedliche Tricks, die in Ihren Alltag passen. Mindestens zwei sollen für Sie noch keine Routine sein. Es geht auch darum, selbst etwas Neues zu lernen.","Testen Sie jeden Tipp im angegebenen Programm und dokumentieren Sie Ihr eigenes Ergebnis. Die Werkbank hilft Ihnen beim einheitlichen Aufbau der Karten.","Beginnen Sie heute mit einer einzigen vollständigen Karte. Lassen Sie diese ausprobieren, bevor Sie die restlichen gestalten. So nehmen Sie die erste Verbesserung gleich in Ihre ganze Sammlung mit."]}]}};
